import * as React from "react";
import {
  FunctionComponent,
  useMemo,
  type CSSProperties,
  useCallback,
} from "react";
import * as styles from "./top-header.module.css";

export type TopHeaderType = {
  className?: string;

  /** Style props */
  exploreColor?: CSSProperties["color"];
  searchColor?: CSSProperties["color"];
  hotelsColor?: CSSProperties["color"];
};

const TopHeader: FunctionComponent<TopHeaderType> = ({
  className = "",
  exploreColor,
  searchColor,
  hotelsColor,
}) => {
  const exploreStyle: CSSProperties = useMemo(() => {
    return {
      color: exploreColor,
    };
  }, [exploreColor]);

  const searchStyle: CSSProperties = useMemo(() => {
    return {
      color: searchColor,
    };
  }, [searchColor]);

  const hotelsStyle: CSSProperties = useMemo(() => {
    return {
      color: hotelsColor,
    };
  }, [hotelsColor]);

  const onHotelsTextClick = useCallback(() => {
    // Please sync "Hotels Page" to the project
  }, []);

  return (
    <header className={[styles.topHeader, className].join(" ")}>
      <div className={styles.topContainer}>
        <img
          className={styles.fickleflightIcon}
          loading="lazy"
          alt=""
          src="/fickleflight.svg"
        />
        <div className={styles.navigationRight}>
          <div className={styles.navigationMenu}>
            <div className={styles.explore} style={exploreStyle}>
              Explore
            </div>
            <div className={styles.search} style={searchStyle}>
              Search
            </div>
            <div
              className={styles.hotels}
              onClick={onHotelsTextClick}
              style={hotelsStyle}
            >
              Hotels
            </div>
            <div className={styles.search}>Offers</div>
          </div>
          <div className={styles.accountSection}>
            <img
              className={styles.hamburgerMenuIcon}
              alt=""
              src="/hamburgermenu@2x.png"
            />
            <img
              className={styles.notificationBellIcon}
              loading="lazy"
              alt=""
              src="/notification-bell@2x.png"
            />
            <img
              className={styles.avatarIcon}
              loading="lazy"
              alt=""
              src="/avatar@2x.png"
            />
          </div>
        </div>
      </div>
    </header>
  );
};

export default TopHeader;
