import * as React from "react";
import { FunctionComponent, useMemo, type CSSProperties } from "react";
import * as styles from "./booking-card.module.css";

export type BookingCardType = {
  className?: string;
  sIAICon?: string;
  singaporeAirlines?: string;
  price?: string;
  depCode?: string;
  depName?: string;
  arrCode?: string;
  arrName?: string;
  flightClass?: string;
  numPeople?: string;
  bookedOn?: string;
  timeAgo?: string;

  /** Style props */
  bookedOnColor?: CSSProperties["color"];
};

const BookingCard: FunctionComponent<BookingCardType> = ({
  className = "",
  sIAICon,
  singaporeAirlines,
  price,
  depCode,
  depName,
  arrCode,
  arrName,
  flightClass,
  numPeople,
  bookedOn,
  bookedOnColor,
  timeAgo,
}) => {
  const bookedOnStyle: CSSProperties = useMemo(() => {
    return {
      color: bookedOnColor,
    };
  }, [bookedOnColor]);

  return (
    <div className={[styles.bookingCard, className].join(" ")}>
      <div className={styles.airlinePrice}>
        <div className={styles.airline}>
          <img className={styles.siaIcon} loading="lazy" alt="" src={sIAICon} />
          <div className={styles.singaporeAirlines}>{singaporeAirlines}</div>
        </div>
        <div className={styles.price}>{price}</div>
      </div>
      <div className={styles.locations}>
        <div className={styles.departure}>
          <div className={styles.depcode}>{depCode}</div>
          <div className={styles.depname}>{depName}</div>
        </div>
        <img className={styles.flightIcon} alt="" src="/flight-icon.svg" />
        <div className={styles.arrival}>
          <div className={styles.depcode}>{arrCode}</div>
          <div className={styles.arrname}>{arrName}</div>
        </div>
      </div>
      <div className={styles.details}>
        <div className={styles.flightClass}>
          <img className={styles.classIcon} alt="" src="/class-icon.svg" />
          <div className={styles.singaporeAirlines}>{flightClass}</div>
        </div>
        <div className={styles.flightClass}>
          <img className={styles.classIcon} alt="" src="/calender.svg" />
          <div className={styles.singaporeAirlines}>{numPeople}</div>
        </div>
      </div>
      <div className={styles.provider}>
        <div className={styles.bookedOnParent}>
          <div className={styles.singaporeAirlines} style={bookedOnStyle}>
            {bookedOn}
          </div>
          <div className={styles.provider1}>Expedia</div>
        </div>
        <div className={styles.timeago}>{timeAgo}</div>
      </div>
    </div>
  );
};

export default BookingCard;
